import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).parent))
from lib import *
E = []
def g(id, term, definition, related=(), cites=()):
    E.append({"kind": "glossary", "id": id, "term": term, "definition": definition, "related": list(related), "citations": list(cites)})

# ---- cortical syndromes and higher function
g("g-prosopagnosia", "Prosopagnosia", "Inability to recognize familiar faces despite intact vision and intact recognition by voice or gait, from damage to the right (or bilateral) fusiform face area and its connections to the anterior temporal lobe. Patients often deny it and rely on hair, glasses or voice.", ["g-agnosia", "g-ventral-stream"], [R("sp-prosopagnosia")])
g("g-apperceptive-agnosia", "Apperceptive agnosia", "Failure to recognize objects because their shape cannot be assembled from the visual input; the patient cannot copy or match the object. Lesions lie in the lateral occipital and occipito-temporal cortex, often bilateral after hypoxia.", ["g-agnosia", "g-associative-agnosia"])
g("g-associative-agnosia", "Associative agnosia", "Failure to recognize an object whose form is perceived normally: the patient can copy and match it but cannot say what it is or how it is used. It reflects disconnection of the visual form areas from the semantic system in the anterior temporal lobe.", ["g-agnosia", "g-apperceptive-agnosia", "g-prosopagnosia"])
g("g-alexia-without-agraphia", "Alexia without agraphia", "Loss of reading with preserved writing after a left occipital infarct that also cuts the splenium, so that visual information from the intact right visual cortex cannot reach the left language cortex. The patient can write a sentence and cannot read it back.", ["g-disconnection-syndrome", "g-homonymous-hemianopia"], [R("sp-alexia"), R("sp-agraphia"), R("sp-corpus-callosum")])
g("g-simultanagnosia", "Simultanagnosia", "Inability to perceive more than one object at a time, so that a scene cannot be taken in as a whole; the patient reads single letters but not words and describes a picture item by item. A sign of bilateral parieto-occipital damage and a component of Balint syndrome.", ["g-optic-ataxia", "g-dorsal-stream"], [R("sp-balint-syndrome"), R("sp-agnosia"), R("sp-posterior-cortical-atrophy")])
g("g-optic-ataxia", "Optic ataxia", "Misreaching for an object under visual guidance despite normal strength, sensation and cerebellar function, from disconnection of the parietal visuomotor cortex from the premotor cortex. Part of Balint syndrome with simultanagnosia and ocular apraxia.", ["g-simultanagnosia", "g-dorsal-stream"])
g("g-akinetopsia", "Akinetopsia", "Loss of the perception of visual motion, so that moving objects appear as a sequence of still frames, after bilateral damage to the temporo-occipital motion area (MT/V5). Acuity, color and form vision remain intact.", ["g-dorsal-stream"])
g("g-achromatopsia-cerebral", "Cerebral achromatopsia", "Loss of color perception with normal cones, from damage to the ventral occipito-temporal cortex (V4 region); unilateral lesions produce hemiachromatopsia in the contralateral field, which is missed unless colors are tested in each hemifield.", ["g-ventral-stream"])
g("g-aprosodia", "Aprosodia", "Loss of the melody, rhythm and emotional intonation of speech (expressive) or of the ability to understand it (receptive), from right hemisphere lesions homologous to the left language areas. The words are correct but sound flat, and irony and anger are missed.", ["g-aphasia"])
g("g-conduction-aphasia", "Conduction aphasia", "Fluent speech with preserved comprehension but disproportionately impaired repetition and phonemic paraphasias that the patient notices and tries to correct, from a lesion of the arcuate fasciculus or the supramarginal gyrus that disconnects the posterior temporal from the frontal speech areas.", ["g-aphasia", "g-paraphasia", "g-disconnection-syndrome"], [R("sp-conduction-aphasia"), R("sp-aphasia")])
g("g-transcortical-aphasia", "Transcortical aphasia", "Aphasia with preserved repetition: the transcortical motor type (reduced fluency, preserved comprehension) follows medial or dorsolateral frontal lesions outside the perisylvian loop, the transcortical sensory type (fluent, impaired comprehension) follows temporo-parieto-occipital lesions, and the mixed type follows watershed infarcts that isolate the intact perisylvian cortex.", ["g-aphasia", "g-watershed"], [R("sp-aphasia")])
g("g-paraphasia", "Paraphasia", "Substitution of an incorrect sound (phonemic: 'tencil' for pencil) or word (semantic: 'fork' for spoon) during speech; a marker of aphasia. Phonemic errors point to the posterior perisylvian and arcuate region, semantic errors to the temporal semantic system and the ventral stream.", ["g-aphasia", "g-conduction-aphasia"])
g("g-apraxia-of-speech", "Apraxia of speech", "Impaired planning and sequencing of the articulatory movements of speech with groping, inconsistent errors and effortful output, despite normal strength of the muscles; a sign of left inferior frontal, insular or opercular lesions and of the non-fluent variant of primary progressive aphasia.", ["g-apraxia", "g-dysarthria"])
g("g-ideomotor-apraxia", "Ideomotor apraxia", "Inability to perform a learned skilled movement to command or by imitation (pantomime tool use, wave goodbye) despite intact strength, sensation and comprehension; from left inferior parietal or premotor lesions, and affecting both hands because the right hemisphere receives its movement formulas through the corpus callosum.", ["g-apraxia", "g-disconnection-syndrome"], [R("sp-apraxia")])
g("g-anosognosia", "Anosognosia", "Unawareness or denial of a deficit, classically of a left hemiplegia after a right parietal stroke or of blindness in Anton syndrome; it prevents the patient from reporting the problem and from engaging in rehabilitation.", ["g-neglect", "g-asomatognosia"])
g("g-asomatognosia", "Asomatognosia", "Failure to recognize a limb as one's own, typically the left arm after a right posterior parietal lesion; the patient may attribute it to someone else or complain that a stranger's arm is in the bed.", ["g-anosognosia", "g-neglect"])
g("g-extinction", "Extinction", "Failure to perceive a stimulus on one side when a competing stimulus is presented simultaneously on the other, although each is perceived alone; the mildest form of neglect, tested with double simultaneous touch, sounds or visual stimuli after right parietal lesions.", ["g-neglect"])
g("g-dysexecutive-syndrome", "Dysexecutive syndrome", "Impairment of planning, initiation, set shifting, inhibition and monitoring with preserved basic language and memory, from dorsolateral prefrontal lesions or their subcortical circuits; tested by fluency, Luria sequences, go/no-go and trail making, and missed by screening tests of memory.", ["g-abulia", "g-frontal-release-signs"])
g("g-abulia", "Abulia", "Loss of initiative, spontaneous speech and movement with preserved ability to respond when prompted, from bilateral medial frontal, anterior cingulate, caudate or anterior thalamic lesions; its extreme form is akinetic mutism.", ["g-akinetic-mutism", "g-dysexecutive-syndrome"], [R("sp-abulia")])
g("g-akinetic-mutism", "Akinetic mutism", "A state of wakefulness with open eyes and visual tracking but no spontaneous movement or speech, after bilateral anterior cingulate and medial frontal damage or bilateral paramedian thalamic lesions; distinguished from coma by the alert appearance and from the locked-in state by the absence of communicative eye movements.", ["g-abulia", "g-locked-in-state"])
g("g-confabulation", "Confabulation", "Production of false memories and answers without intent to deceive, filling gaps in memory; characteristic of diencephalic and basal forebrain amnesia (Korsakoff syndrome, anterior communicating aneurysm rupture) and of frontal lobe dysfunction rather than of pure hippocampal amnesia.", ["g-papez-circuit"], [R("sp-wernicke-encephalopathy"), R("sp-frontal-lobe-syndrome")])
g("g-frontal-release-signs", "Frontal release signs", "Primitive reflexes that reappear with frontal or diffuse cerebral damage: the grasp, palmomental, snout, rooting and glabellar tap responses. Individually nonspecific, together they suggest frontal disinhibition.", ["g-dysexecutive-syndrome"])
g("g-disconnection-syndrome", "Disconnection syndrome", "A deficit produced by interrupting the white-matter connection between two intact cortical areas rather than by destroying either: conduction aphasia (arcuate fasciculus), alexia without agraphia (splenium), left-hand apraxia and agraphia (callosal body), and the split-brain syndrome after callosotomy.", ["g-conduction-aphasia", "g-alexia-without-agraphia"], [R("sp-conduction-aphasia"), R("sp-corpus-callosum"), R("sp-alexia")])
g("g-papez-circuit", "Papez circuit", "The limbic loop of memory: hippocampus and subiculum, fornix, mammillary body, mammillothalamic tract, anterior thalamic nuclei, cingulate gyrus and cingulum, entorhinal cortex and back to the hippocampus. Interruption at any point produces anterograde amnesia.", ["g-confabulation"], [R("sp-limbic-system"), R("sp-mammillary-bodies"), R("sp-cingulate-cortex")])
g("g-default-mode-network", "Default mode network", "The set of regions (medial prefrontal cortex, posterior cingulate and precuneus, angular gyri, hippocampal formation) that is most active at rest and during self-referential thought and memory retrieval and deactivates during attention-demanding tasks; its posterior hub is the first to lose metabolism in Alzheimer disease.", ["g-papez-circuit"])
g("g-dorsal-stream", "Dorsal visual stream", "The occipito-parietal pathway that computes where objects are and how to act on them (location, motion, reaching, attention); lesions produce optic ataxia, simultanagnosia, akinetopsia and neglect. The 'where' or 'how' pathway.", ["g-ventral-stream", "g-optic-ataxia"])
g("g-ventral-stream", "Ventral visual stream", "The occipito-temporal pathway that identifies what is seen (shape, color, faces, words, objects), running from the primary visual cortex through the fusiform and inferior temporal cortex to the anterior temporal lobe; lesions produce agnosia, prosopagnosia, achromatopsia and alexia.", ["g-dorsal-stream", "g-prosopagnosia"])
g("g-quadrantanopia", "Quadrantanopia", "Loss of one quadrant of the visual field in both eyes: a superior quadrantanopia follows lesions of Meyer's loop in the temporal lobe or the lower calcarine bank; an inferior quadrantanopia follows lesions of the parietal optic radiation or the upper calcarine bank.", ["g-homonymous-hemianopia", "g-meyer-loop"], [R("sp-homonymous-superior-quadrantanopia")])
g("g-meyer-loop", "Meyer's loop", "The anterior sweep of the inferior fibers of the optic radiation over the temporal horn before they turn back to the lower calcarine cortex; it carries the contralateral upper visual field and is cut by anterior temporal lobectomy, producing a superior quadrantanopia.", ["g-quadrantanopia"], [R("sp-visual-pathway"), R("sp-homonymous-superior-quadrantanopia"), R("sp-temporal-lobe")])
g("g-cortical-magnification", "Cortical magnification", "The disproportionate area of visual cortex devoted to the central few degrees of the visual field, mapped to the occipital pole; it explains why macular vision survives partial calcarine lesions and why the macula is represented at the pole where two arteries meet.", ["g-retinotopy", "g-macular-sparing"])
g("g-visual-word-form-area", "Visual word form area", "A region of the left posterior fusiform gyrus that learns to recognize letter strings and familiar words as visual wholes; its damage produces pure alexia with letter-by-letter reading whose time grows with word length.", ["g-alexia-without-agraphia", "g-ventral-stream"])
g("g-fusiform-face-area", "Fusiform face area", "A region of the right posterior fusiform gyrus that responds selectively to faces and extracts the configuration that identifies an individual; its damage produces prosopagnosia.", ["g-prosopagnosia", "g-ventral-stream"])
# ---- white matter and vascular
g("g-association-fibers", "Association fibers", "White-matter axons connecting cortical areas within one hemisphere: short U-fibers between neighboring gyri and the long fasciculi (arcuate and superior longitudinal, inferior longitudinal, inferior fronto-occipital, uncinate, cingulum) that link the lobes into networks.", ["g-commissural-fibers", "g-projection-fibers"], [R("sp-corpus-callosum"), R("sp-prefrontal-association-cortex"), R("sp-gray-matter")])
g("g-commissural-fibers", "Commissural fibers", "Axons crossing between the hemispheres: the corpus callosum, the anterior commissure (temporal and olfactory), the hippocampal commissure and the posterior commissure (pretectal and vertical gaze fibers).", ["g-association-fibers", "g-disconnection-syndrome"], [R("sp-corpus-callosum"), R("sp-cerebral-cortex")])
g("g-projection-fibers", "Projection fibers", "Axons connecting the cortex with subcortical structures, brainstem and spinal cord: corticospinal, corticobulbar, corticopontine and corticostriatal fibers descending, and thalamocortical radiations ascending, gathered in the corona radiata and internal capsule.", ["g-association-fibers", "g-internal-capsule"], [R("sp-internal-capsule"), R("sp-thalamocortical-radiations"), R("sp-corticospinal-cord-tract")])
g("g-internal-capsule", "Internal capsule", "The compact band of projection fibers between the caudate and thalamus medially and the lentiform nucleus laterally, with an anterior limb (frontopontine and anterior thalamic radiation), a genu (corticobulbar), a posterior limb (corticospinal and sensory thalamocortical fibers), and retrolenticular and sublenticular parts (optic and acoustic radiations). Lacunes here produce pure motor or sensorimotor stroke.", ["g-projection-fibers", "g-lacune"], [R("sp-internal-capsule")])
g("g-u-fibers", "U-fibers", "Short subcortical association fibers that arch beneath a sulcus to connect adjacent gyri; their sparing (metachromatic leukodystrophy, small vessel disease) or involvement (Canavan disease, some toxic leukoencephalopathies) helps classify white-matter disease on MRI.", ["g-association-fibers", "g-leukodystrophy"])
g("g-wallerian-degeneration", "Wallerian degeneration", "Breakdown of the axon and its myelin distal to an injury, with Schwann cell tubes persisting in the peripheral nerve to guide regeneration; in the central nervous system it is visible on MRI as signal change and atrophy of a tract (the cerebral peduncle after a capsular stroke) months later.", ["g-neurapraxia", "g-axonotmesis"], [R("sp-peripheral-nerve-injury"), R("sp-axonotmesis"), R("sp-schwann-cells")])
g("g-neurapraxia", "Neurapraxia", "The mildest nerve injury: a focal conduction block from demyelination or ischemia without axonal loss, recovering in days to weeks; the Saturday night radial palsy and a tourniquet palsy are examples. Distal nerve conduction is preserved.", ["g-axonotmesis", "g-neurotmesis"], [R("sp-neurapraxia")])
g("g-axonotmesis", "Axonotmesis", "Nerve injury in which axons are interrupted but the connective tissue tubes remain, so that Wallerian degeneration is followed by regeneration along the tubes at about a millimeter a day; typical of traction and crush injuries.", ["g-neurapraxia", "g-neurotmesis", "g-wallerian-degeneration"], [R("sp-axonotmesis")])
g("g-neurotmesis", "Neurotmesis", "Complete transection of a nerve including its connective tissue sheaths; regeneration fails or forms a neuroma unless the nerve is surgically repaired or grafted.", ["g-axonotmesis", "g-tinel-sign"], [R("sp-neurotmesis")])
g("g-tinel-sign", "Tinel sign", "Tingling in the distribution of a nerve produced by tapping over it, marking a site of entrapment (carpal tunnel) or the advancing front of regenerating axons after injury.", ["g-axonotmesis", "g-mononeuropathy"])
g("g-synkinesis", "Synkinesis", "Involuntary movement accompanying a voluntary one because regenerating axons have reached the wrong targets, as when the eye closes on smiling after facial nerve recovery; crocodile tears (lacrimation on eating) are the autonomic form.", ["g-axonotmesis"])
g("g-chromatolysis", "Chromatolysis", "The reaction of a neuron whose axon has been cut: swelling of the cell body, dispersal of Nissl substance and displacement of the nucleus to the periphery as the cell switches from transmission to regeneration.", ["g-wallerian-degeneration"], [R("sp-peripheral-nerve-injury"), R("sp-neurons")])
g("g-charcot-bouchard-aneurysm", "Charcot-Bouchard microaneurysm", "Small dilatation of a perforating artery (lenticulostriate, thalamoperforating, pontine) weakened by chronic hypertension; its rupture produces the deep hypertensive hemorrhages of the putamen, thalamus, pons and cerebellum.", ["g-lacune"], [R("sp-charcot-bouchard-aneurysm")])
g("g-amyloid-angiopathy", "Cerebral amyloid angiopathy", "Deposition of amyloid-beta in the walls of cortical and leptomeningeal arteries in the elderly, producing lobar hemorrhages, cortical microbleeds and superficial siderosis on susceptibility imaging, and transient focal neurological episodes; a contraindication to anticoagulation when severe.", ["g-charcot-bouchard-aneurysm"], [R("sp-cerebral-amyloid-angiopathy")])
g("g-artery-of-percheron", "Artery of Percheron", "A variant in which a single paramedian thalamic artery from one P1 segment supplies both medial thalami and the rostral midbrain; its occlusion produces bilateral paramedian thalamic infarcts with sudden coma or hypersomnolence, vertical gaze palsy and amnesia.", ["g-top-of-basilar-syndrome"], [R("sp-thalamic-nuclei"), R("sp-posterior-cerebral-arteries"), R("sp-posterior-cerebral-artery-stroke")])
g("g-top-of-basilar-syndrome", "Top of the basilar syndrome", "Embolic occlusion of the distal basilar artery infarcting the midbrain, thalami and occipital lobes: somnolence, vertical gaze and pupillary abnormalities, visual field loss or cortical blindness, hallucinations and amnesia, often without weakness.", ["g-artery-of-percheron"], [R("sp-basilar-artery-occlusion"), R("sp-basilar-artery"), R("sp-posterior-cerebral-artery-stroke")])
g("g-malignant-mca-infarct", "Malignant middle cerebral artery infarct", "Infarction of most of the MCA territory with cytotoxic edema that peaks at 2-4 days and produces midline shift and herniation; decompressive hemicraniectomy within 48 hours improves survival, especially in patients under 60.", ["g-herniation", "g-penumbra"], [R("sp-middle-cerebral-artery-stroke"), R("sp-cerebral-edema"), R("sp-brain-herniation")])
g("g-insular-ribbon-sign", "Insular ribbon sign", "Loss of the gray-white distinction of the insular cortex on non-contrast CT within hours of a middle cerebral artery occlusion; the insula is the most distal perforator territory and the first to fail.", ["g-hyperdense-artery-sign", "g-aspects"], [R("sp-insular-cortex"), R("sp-stroke-imaging"), R("sp-middle-cerebral-artery-stroke")])
g("g-hyperdense-artery-sign", "Hyperdense artery sign", "Increased density of an occluded artery on non-contrast CT (the hyperdense MCA or basilar sign) from the fresh thrombus within it; an early marker of large vessel occlusion.", ["g-insular-ribbon-sign"], [R("sp-stroke-imaging"), R("sp-middle-cerebral-artery-stroke"), R("sp-ischemic-stroke")])
g("g-aspects", "ASPECTS", "The Alberta Stroke Program Early CT Score: ten regions of the MCA territory on two CT levels, one point deducted for each region with early ischemic change; low scores predict poor outcome and hemorrhage after reperfusion.", ["g-insular-ribbon-sign", "g-penumbra"])
g("g-core-penumbra-mismatch", "Core-penumbra mismatch", "The difference between the irreversibly infarcted core (low blood volume or restricted diffusion) and the larger hypoperfused but viable penumbra on perfusion imaging; a large mismatch identifies patients who benefit from late thrombectomy.", ["g-penumbra", "g-aspects"])
g("g-spot-sign", "Spot sign", "A focus of contrast extravasation within an acute intracerebral hematoma on CT angiography, predicting hematoma expansion and worse outcome.", ["g-charcot-bouchard-aneurysm"])
g("g-dawson-fingers", "Dawson fingers", "Ovoid demyelinating lesions oriented perpendicular to the lateral ventricles along the deep medullary veins, seen on sagittal FLAIR in multiple sclerosis; a discriminating feature against vascular white-matter disease.", ["g-flair", "g-u-fibers"], [R("sp-multiple-sclerosis"), R("sp-white-matter-lesions")])
g("g-empty-delta-sign", "Empty delta sign", "A filling defect in the enhancing superior sagittal sinus on contrast CT or MRI, marking thrombus within the sinus in cerebral venous thrombosis.", [], [R("sp-cerebral-venous-sinus-thrombosis"), R("sp-dural-venous-sinuses")])
g("g-crossed-cerebellar-diaschisis", "Crossed cerebellar diaschisis", "Reduced metabolism and blood flow of the cerebellar hemisphere opposite a large cerebral lesion, from loss of corticopontocerebellar input, seen on PET and perfusion imaging; not an infarct.", [])
# ---- development and pediatrics
g("g-neurulation", "Neurulation", "Folding and closure of the neural plate into the neural tube during the third and fourth weeks; failure at the anterior neuropore produces anencephaly and at the posterior neuropore spina bifida.", ["g-heterotopia"], [R("sp-neural-tube"), R("sp-neural-tube-development-and-stages"), R("sp-anencephaly")])
g("g-holoprosencephaly", "Holoprosencephaly", "Failure of the forebrain to divide into two hemispheres, from alobar (a single ventricle, cyclopia) to lobar (fused frontal lobes, absent septum pellucidum), associated with midline facial defects, sonic hedgehog pathway mutations and trisomy 13.", ["g-neurulation"], [R("sp-holoprosencephaly")])
g("g-lissencephaly", "Lissencephaly", "A smooth brain with absent or shallow sulci and a thick, abnormally layered cortex from arrested neuronal migration (LIS1, DCX and other genes), presenting with severe developmental delay and epilepsy.", ["g-heterotopia", "g-polymicrogyria"], [R("sp-lissencephaly")])
g("g-heterotopia", "Heterotopia", "Gray matter in the wrong place, along the ventricular wall (periventricular nodular) or as a band within the white matter, because neurons stopped migrating; it follows gray matter signal on all MRI sequences, does not enhance, and is a common cause of epilepsy.", ["g-lissencephaly", "g-polymicrogyria"])
g("g-polymicrogyria", "Polymicrogyria", "An excess of small, fused gyri with a thick irregular cortex from abnormal late cortical organization, often perisylvian and bilateral, producing pseudobulbar palsy, epilepsy and developmental delay.", ["g-heterotopia", "g-lissencephaly"])
g("g-focal-cortical-dysplasia", "Focal cortical dysplasia", "A localized malformation of cortical development with disorganized layers, dysmorphic neurons and balloon cells, seen on MRI as cortical thickening, blurred gray-white junction and a transmantle FLAIR band; a leading cause of surgically treatable epilepsy.", ["g-heterotopia"], [R("sp-partial-epilepsy"), R("sp-neuroimaging-in-epilepsy-surgery"), R("sp-epilepsy-surgery")])
g("g-dandy-walker-malformation", "Dandy-Walker malformation", "Cystic dilatation of the fourth ventricle with hypoplasia and upward rotation of the cerebellar vermis and an enlarged posterior fossa, presenting with hydrocephalus and ataxia.", ["g-hydrocephalus"], [R("sp-dandy-walker-malformation")])
g("g-tethered-cord", "Tethered cord", "Abnormal fixation of the low-lying conus by a thick filum, lipoma or scar so that growth stretches the cord, producing progressive leg weakness, foot deformity, back pain and bladder dysfunction in childhood or adolescence.", ["g-conus-medullaris"], [R("sp-tethered-cord-syndrome")])
g("g-periventricular-leukomalacia", "Periventricular leukomalacia", "Ischemic necrosis of the periventricular white matter of the premature brain, injuring the leg fibers of the corticospinal tract and the optic radiation and producing spastic diplegia and visual perceptual deficits; seen as periventricular white-matter loss and irregular ventricular margins.", ["g-watershed"], [R("sp-cerebral-palsy"), R("sp-periventricular-and-intraventricular-hemorrhage")])
g("g-kernicterus", "Kernicterus", "Bilirubin toxicity of the neonatal brain, selectively damaging the globus pallidus, subthalamic nucleus, hippocampus and brainstem nuclei and producing dyskinetic cerebral palsy, deafness and upgaze palsy; the immature blood-brain barrier lets unconjugated bilirubin in.", ["g-blood-brain-barrier"])
g("g-infantile-spasms", "Infantile spasms", "Clusters of brief flexor or extensor jerks in infancy with a chaotic high-voltage EEG (hypsarrhythmia) and developmental regression, signaling a serious underlying cause such as tuberous sclerosis or a malformation and demanding urgent treatment.", ["g-hypsarrhythmia"], [R("sp-infantile-epileptic-spasms-syndrome")])
g("g-hypsarrhythmia", "Hypsarrhythmia", "The chaotic, high-amplitude, multifocal spike-and-slow-wave EEG pattern of infantile spasms.", ["g-infantile-spasms"])
g("g-floppy-infant", "Floppy infant", "An infant with hypotonia; if weak with absent reflexes and tongue fasciculation the cause is a lower motor neuron disorder (spinal muscular atrophy, congenital myopathy, neuromuscular junction), if strong with brisk reflexes a central cause (hypoxic injury, chromosomal or metabolic disease).", ["g-lower-motor-neuron"])
# ---- physiology, CSF, transmitters, sleep
g("g-blood-brain-barrier", "Blood–brain barrier", "The tight-junctioned capillary endothelium with its astrocyte end-feet and pericytes that excludes proteins, most drugs and hydrophilic molecules from the brain; it is absent in the circumventricular organs and breaks down in tumor, infection, inflammation and infarction, which is what contrast enhancement shows.", ["g-circumventricular-organs", "g-vasogenic-edema"], [R("sp-blood-brain-barrier"), R("sp-blood-brain-barrier-2")])
g("g-circumventricular-organs", "Circumventricular organs", "Midline structures around the ventricles that lack a blood-brain barrier and sense or secrete into the blood: the area postrema, median eminence, organum vasculosum, subfornical organ, pineal gland and posterior pituitary. They enhance normally after contrast.", ["g-blood-brain-barrier"], [R("sp-area-postrema"), R("sp-blood-brain-barrier-2"), R("sp-osmoreceptors")])
g("g-vasogenic-edema", "Vasogenic edema", "Extracellular fluid leaking through a broken blood-brain barrier and spreading through the white matter around tumors, abscesses and hemorrhages, sparing the cortex and responding to dexamethasone; contrasted with cytotoxic edema, the cell swelling of infarction that involves gray and white matter and restricts diffusion.", ["g-blood-brain-barrier", "g-dwi"])
g("g-monro-kellie-doctrine", "Monro-Kellie doctrine", "Within the rigid skull the volumes of brain, blood and CSF are constant, so an added volume (mass, edema, hematoma) must displace CSF or venous blood; when that compensation is exhausted, intracranial pressure rises steeply and herniation follows.", ["g-herniation", "g-cushing-response"], [R("sp-increased-intracranial-pressure"), R("sp-intracranial-pressure-monitoring"), R("sp-cerebral-edema")])
g("g-transependymal-edema", "Transependymal edema", "A halo of FLAIR hyperintensity around the ventricles in acute obstructive hydrocephalus, from CSF forced through the ependyma into the periventricular white matter.", ["g-hydrocephalus"])
g("g-xanthochromia", "Xanthochromia", "Yellow discoloration of the CSF supernatant from bilirubin, appearing about twelve hours after subarachnoid hemorrhage and persisting for two weeks; it distinguishes true hemorrhage from a traumatic tap.", [], [R("sp-xanthochromia")])
g("g-oligoclonal-bands", "Oligoclonal bands", "Discrete immunoglobulin bands on CSF electrophoresis that are absent from the serum, indicating intrathecal antibody synthesis; present in most patients with multiple sclerosis and in chronic CNS infections.", [], [R("sp-multiple-sclerosis"), R("sp-cerebrospinal-fluid")])
g("g-glymphatic-system", "Glymphatic system", "The perivascular pathway along which CSF flows into the brain and interstitial fluid and solutes are cleared to the venous and lymphatic drainage, most active during sleep; implicated in the clearance of amyloid.", ["g-blood-brain-barrier"])
g("g-excitotoxicity", "Excitotoxicity", "Neuronal death caused by excessive glutamate acting on NMDA receptors, flooding the cell with calcium; the mechanism of neuronal loss in ischemia, status epilepticus, hypoglycemia and trauma.", ["g-nmda-receptor"], [R("sp-nmda-receptor"), R("sp-hypoxic-ischemic-encephalopathy")])
g("g-nmda-receptor", "NMDA receptor", "A glutamate receptor that opens only when glutamate binds and the membrane is depolarized, admitting calcium; the coincidence detector of long-term potentiation and the mediator of excitotoxicity, blocked by ketamine and targeted by the antibodies of anti-NMDA receptor encephalitis.", ["g-excitotoxicity", "g-long-term-potentiation"])
g("g-long-term-potentiation", "Long-term potentiation", "A lasting increase in synaptic strength after brief high-frequency activity, best studied at the CA3-CA1 synapse of the hippocampus and dependent on NMDA receptors; the cellular model of memory storage.", ["g-nmda-receptor", "g-papez-circuit"])
g("g-nigrostriatal-pathway", "Nigrostriatal pathway", "The dopaminergic projection from the substantia nigra pars compacta to the putamen and caudate that sets the gain of the basal ganglia loops; its degeneration causes Parkinson disease and its blockade drug-induced parkinsonism.", ["g-mesolimbic-pathway", "g-bradykinesia"], [R("sp-substantia-nigra"), R("sp-basal-ganglia"), R("sp-parkinson-disease")])
g("g-mesolimbic-pathway", "Mesolimbic and mesocortical pathways", "Dopaminergic projections from the ventral tegmental area to the nucleus accumbens, amygdala and hippocampus (mesolimbic: reward, motivation, addiction, psychosis) and to the prefrontal cortex (mesocortical: working memory, motivation).", ["g-nigrostriatal-pathway"])
g("g-serotonin-syndrome", "Serotonin syndrome", "A toxic state from excess serotonergic activity (drug combinations) with agitation, clonus, hyperreflexia, tremor, sweating, diarrhea and hyperthermia; the clonus and rapid onset distinguish it from neuroleptic malignant syndrome.", ["g-anticholinergic-toxicity"])
g("g-anticholinergic-toxicity", "Anticholinergic toxicity", "Delirium with dilated pupils, dry skin, urinary retention, tachycardia and hyperthermia from muscarinic blockade; a common reversible cause of confusion in the elderly on bladder, sleep and allergy drugs.", ["g-serotonin-syndrome"])
g("g-orexin", "Orexin (hypocretin)", "A peptide made by lateral hypothalamic neurons that stabilizes wakefulness by exciting the arousal nuclei; loss of these neurons causes narcolepsy type 1 with cataplexy and low CSF hypocretin.", ["g-cataplexy", "g-ascending-arousal-system"], [R("sp-cataplexy"), R("sp-pediatric-narcolepsy"), R("sp-hypothalamus")])
g("g-cataplexy", "Cataplexy", "Sudden loss of muscle tone triggered by emotion, especially laughter, with preserved consciousness; the intrusion of REM sleep atonia into wakefulness, pathognomonic of narcolepsy with orexin deficiency.", ["g-orexin", "g-rem-sleep-behavior-disorder"])
g("g-rem-sleep-behavior-disorder", "REM sleep behavior disorder", "Loss of the normal atonia of REM sleep so that dreams are acted out, from dysfunction of the pontine REM circuits; it precedes Parkinson disease, Lewy body dementia and multiple system atrophy by years.", ["g-cataplexy", "g-ascending-arousal-system"], [R("sp-rapid-eye-movement-sleep-behavior-disorder"), R("sp-rem-sleep")])
g("g-ascending-arousal-system", "Ascending reticular activating system", "The cholinergic, monoaminergic, orexinergic and glutamatergic projections from the upper brainstem and hypothalamus to the thalamus and cortex that maintain wakefulness; damage to the paramedian upper pons and midbrain, or bilateral thalamic damage, produces coma.", ["g-orexin", "g-locked-in-state"], [R("sp-reticular-activating-system")])
g("g-sleep-spindle", "Sleep spindle", "A brief 12-14 Hz burst on the EEG of stage N2 sleep generated by the thalamic reticular nucleus and thalamocortical loops; with K-complexes it marks light non-REM sleep.", ["g-alpha-rhythm"])
g("g-alpha-rhythm", "Alpha rhythm", "The 8-13 Hz posterior EEG rhythm of relaxed wakefulness with the eyes closed that attenuates on eye opening; its slowing or loss indicates encephalopathy.", ["g-sleep-spindle", "g-triphasic-waves"])
g("g-triphasic-waves", "Triphasic waves", "Generalized, frontally predominant three-phase EEG waves seen in metabolic encephalopathies, classically hepatic and uremic; nonspecific but suggestive when the EEG is diffusely slow.", ["g-alpha-rhythm", "g-periodic-discharges"])
g("g-periodic-discharges", "Periodic discharges", "Repetitive epileptiform complexes at regular intervals on the EEG: lateralized (PLEDs) over an acute cortical injury such as herpes encephalitis or stroke, generalized in prion disease and after anoxia.", ["g-triphasic-waves", "g-burst-suppression"])
g("g-burst-suppression", "Burst suppression", "An EEG pattern of bursts of activity alternating with periods of flat suppression, seen with deep anesthesia, hypothermia and severe anoxic injury; a poor prognostic sign after cardiac arrest.", ["g-periodic-discharges"])
# ---- epilepsy and headache
g("g-aura", "Aura", "The first subjective symptom of a focal seizure, produced by discharge in the cortex of onset and therefore the best localizing feature: epigastric rising and fear for the medial temporal lobe, colored shapes for the occipital lobe, tingling for the parietal lobe. Migraine aura is a spreading cortical event of minutes rather than seconds.", ["g-jacksonian-march", "g-cortical-spreading-depression"], [R("sp-seizure"), R("sp-focal-onset-seizure"), R("sp-migraine-with-aura")])
g("g-jacksonian-march", "Jacksonian march", "Spread of clonic jerking from one body part to adjacent parts (thumb to hand to arm to face) as a seizure discharge moves along the motor homunculus of the precentral gyrus.", ["g-aura", "g-todd-paresis", "g-homunculus"], [R("sp-focal-onset-seizure"), R("sp-precentral-gyrus"), R("sp-motor-cortical")])
g("g-todd-paresis", "Todd paresis", "Transient weakness of the body part involved in a focal motor seizure, lasting minutes to hours after it ends, from exhaustion of the motor cortex; it localizes the focus and can mimic a stroke.", ["g-jacksonian-march"], [R("sp-postictal-seizure-state"), R("sp-stroke-mimics"), R("sp-focal-onset-seizure")])
g("g-absence-seizure", "Absence seizure", "A brief generalized seizure of childhood with a blank stare, eyelid flutter and immediate recovery, produced by 3 Hz spike-and-wave discharges in thalamocortical circuits and provoked by hyperventilation; some drugs for focal epilepsy make it worse.", ["g-aura"], [R("sp-absence-seizure")])
g("g-febrile-seizure", "Febrile seizure", "A generalized seizure with fever in a neurologically normal child between six months and five years, usually brief and benign; complex features (focal, prolonged, repeated) raise the risk of later epilepsy and require evaluation.", ["g-absence-seizure"])
g("g-status-epilepticus", "Status epilepticus", "A seizure lasting more than five minutes or seizures recurring without recovery; a medical emergency treated with benzodiazepines then a loading antiepileptic, because prolonged seizures cause excitotoxic neuronal death. Non-convulsive status is an unrecognized cause of coma diagnosed only by EEG.", ["g-excitotoxicity"], [R("sp-status-epilepticus"), R("sp-electrical-status-epilepticus-in-sleep"), R("sp-new-onset-refractory-status-epilepticus")])
g("g-cortical-spreading-depression", "Cortical spreading depression", "A slowly propagating wave of neuronal depolarization followed by silence that travels across the cortex at a few millimeters a minute; the mechanism of the migraine aura, whose scintillations march across the visual field over twenty minutes.", ["g-aura", "g-trigeminocervical-complex"], [R("sp-migraine-with-aura"), R("sp-migraine-headache")])
g("g-trigeminocervical-complex", "Trigeminocervical complex", "The caudal spinal trigeminal nucleus and the C1-C3 dorsal horns, where afferents from the dura, the cranial vessels and the upper neck converge; it explains referral of head pain between the face, occiput and neck and is the relay of migraine and cervicogenic headache.", ["g-cortical-spreading-depression", "g-thunderclap-headache"], [R("sp-spinal-trigeminal-nucleus"), R("sp-cervicogenic-headache"), R("sp-migraine-headache")])
g("g-thunderclap-headache", "Thunderclap headache", "A severe headache reaching maximum intensity within a minute; subarachnoid hemorrhage until proved otherwise by CT within six hours or lumbar puncture, with reversible vasoconstriction, dissection, venous thrombosis and pituitary apoplexy as the alternatives.", ["g-xanthochromia", "g-trigeminocervical-complex"], [R("sp-thunderclap-headache")])
g("g-trigeminal-autonomic-cephalalgia", "Trigeminal autonomic cephalalgia", "A group of strictly unilateral orbital headaches with ipsilateral lacrimation, nasal congestion, ptosis and miosis from parasympathetic activation and sympathetic deficit: cluster headache, paroxysmal hemicrania, SUNCT and hemicrania continua, distinguished by attack duration and treatment response.", ["g-trigeminocervical-complex"], [R("sp-cluster-headache"), R("sp-chronic-paroxysmal-hemicrania"), R("sp-spinal-trigeminal-nucleus")])
# ---- dementia and movement
g("g-neurofibrillary-tangle", "Neurofibrillary tangle", "Intraneuronal aggregate of hyperphosphorylated tau protein that appears first in the entorhinal cortex and spreads to the hippocampus and association cortex in Alzheimer disease; tangle stage tracks the cognitive decline better than amyloid plaques.", ["g-amyloid-plaque", "g-lewy-body"], [R("sp-alzheimer-disease"), R("sp-amyloid-beta-peptide"), R("sp-pick-disease")])
g("g-amyloid-plaque", "Amyloid plaque", "Extracellular deposit of amyloid-beta in the neocortex, accumulating years before symptoms in Alzheimer disease; detected by amyloid PET and by low CSF amyloid-beta 42.", ["g-neurofibrillary-tangle"], [R("sp-amyloid-beta-peptide"), R("sp-alzheimer-disease")])
g("g-lewy-body", "Lewy body", "Intraneuronal inclusion of alpha-synuclein found in the substantia nigra, brainstem nuclei and cortex in Parkinson disease and dementia with Lewy bodies; the pathology spreads from the olfactory bulb and vagal nucleus upward.", ["g-neurofibrillary-tangle", "g-rem-sleep-behavior-disorder"], [R("sp-lewy-bodies"), R("sp-lewy-body-dementia")])
g("g-semantic-dementia", "Semantic dementia", "Progressive loss of the meaning of words and of knowledge about objects and people with fluent, empty speech, from asymmetric anterior temporal lobe atrophy; a variant of frontotemporal lobar degeneration.", ["g-logopenic-aphasia", "g-posterior-cortical-atrophy"], [R("sp-primary-progressive-aphasia"), R("sp-frontotemporal-lobe-dementia"), R("sp-temporal-lobe")])
g("g-logopenic-aphasia", "Logopenic progressive aphasia", "Progressive word-finding pauses and impaired sentence repetition with preserved grammar and single-word comprehension, from left temporo-parietal atrophy, usually caused by Alzheimer pathology.", ["g-semantic-dementia"], [R("sp-primary-progressive-aphasia")])
g("g-posterior-cortical-atrophy", "Posterior cortical atrophy", "A visual variant of Alzheimer disease beginning in the occipito-parietal and occipito-temporal cortex with simultanagnosia, optic ataxia, alexia and visual agnosia while memory is relatively preserved.", ["g-simultanagnosia", "g-semantic-dementia"], [R("sp-posterior-cortical-atrophy")])
g("g-corticobasal-syndrome", "Corticobasal syndrome", "Asymmetric parkinsonism with limb apraxia, dystonia, myoclonus, cortical sensory loss and an alien limb, from asymmetric frontoparietal and basal ganglia degeneration (corticobasal degeneration or Alzheimer pathology).", ["g-ideomotor-apraxia", "g-hummingbird-sign"], [R("sp-corticobasal-degeneration")])
g("g-hummingbird-sign", "Hummingbird sign", "The silhouette of the atrophic midbrain with a preserved pons on midline sagittal MRI in progressive supranuclear palsy, resembling a hummingbird's head and beak.", ["g-hot-cross-bun-sign", "g-corticobasal-syndrome"], [R("sp-progressive-supranuclear-palsy"), R("sp-parkinson-plus-syndrome")])
g("g-hot-cross-bun-sign", "Hot cross bun sign", "A cruciform T2 hyperintensity in the pons from degeneration of the transverse pontocerebellar fibers and the raphe, seen in the cerebellar type of multiple system atrophy.", ["g-hummingbird-sign"], [R("sp-shy-drager-syndrome"), R("sp-parkinson-plus-syndrome")])
g("g-swallow-tail-sign", "Swallow tail sign", "The normal hyperintense nigrosome-1 in the dorsolateral substantia nigra on susceptibility-weighted MRI, shaped like a swallow's tail; its loss supports Parkinson disease and other nigral degenerations.", ["g-dopamine-transporter-imaging"])
g("g-dopamine-transporter-imaging", "Dopamine transporter imaging (DaTscan)", "SPECT imaging of the presynaptic dopamine transporter in the striatum; reduced, asymmetric putaminal uptake indicates nigrostriatal degeneration (Parkinson disease, Lewy body dementia, atypical parkinsonism) and is normal in essential tremor and drug-induced parkinsonism.", ["g-swallow-tail-sign", "g-nigrostriatal-pathway"])
g("g-eye-of-the-tiger-sign", "Eye of the tiger sign", "Central T2 hyperintensity within a hypointense globus pallidus on MRI, from iron accumulation with central gliosis, characteristic of pantothenate kinase-associated neurodegeneration.", ["g-hummingbird-sign"])
g("g-holmes-tremor", "Holmes (rubral) tremor", "A slow, coarse tremor present at rest and worsening with posture and action, appearing weeks to months after a lesion of the midbrain or thalamus that damages both the cerebellothalamic and nigrostriatal pathways.", ["g-tremor"], [R("sp-holmes-tremor")])
g("g-leukodystrophy", "Leukodystrophy", "A genetic disorder of myelin formation or maintenance producing symmetric, confluent white-matter disease with progressive spasticity, ataxia and cognitive decline; the regional pattern on MRI (parieto-occipital, frontal, periventricular) and associated features point to the gene.", ["g-u-fibers", "g-heteroplasmy"], [R("sp-metachromatic-leukodystrophy")])
g("g-heteroplasmy", "Heteroplasmy", "The coexistence of normal and mutant mitochondrial DNA within a cell, varying between tissues and relatives, which explains the variable expression and maternal inheritance of mitochondrial disorders such as MELAS.", ["g-leukodystrophy", "g-ragged-red-fibers"], [R("sp-melas-syndrome"), R("sp-myoclonic-epilepsy-and-ragged-red-fibers"), R("sp-genetics-inheritance-patterns")])
g("g-ragged-red-fibers", "Ragged red fibers", "Muscle fibers with subsarcolemmal accumulations of abnormal mitochondria that stain red with modified Gomori trichrome; the histological hallmark of mitochondrial myopathy.", ["g-heteroplasmy"], [R("sp-myoclonic-epilepsy-and-ragged-red-fibers")])
# ---- tumors, infection, coma
g("g-ring-enhancement", "Ring enhancement", "A rim of contrast enhancement around a non-enhancing center, produced by a necrotic tumor (glioblastoma, metastasis), an abscess (thin smooth wall, central restricted diffusion), a resolving hematoma or tumefactive demyelination (incomplete ring); the wall, the diffusion and the time course separate them.", ["g-vasogenic-edema", "g-dural-tail"], [R("sp-brain-abscess"), R("sp-glioblastoma-multiforme"), R("sp-brain-metastasis")])
g("g-dural-tail", "Dural tail", "A tapering strip of enhancing dura extending from the margin of an extra-axial mass, typical of meningioma.", ["g-ring-enhancement"], [R("sp-meningioma"), R("sp-dura-mater")])
g("g-butterfly-glioma", "Butterfly glioma", "A glioblastoma (or lymphoma) that crosses the corpus callosum to involve both frontal lobes in a butterfly shape.", ["g-ring-enhancement"], [R("sp-glioblastoma-multiforme"), R("sp-corpus-callosum")])
g("g-pancoast-tumor", "Pancoast tumor", "An apical lung tumor invading the lower trunk of the brachial plexus (C8-T1) and the stellate ganglion, producing shoulder and medial arm pain, hand wasting and a Horner syndrome.", ["g-horner-syndrome", "g-plexopathy"], [R("sp-lung-pancoast-tumor"), R("sp-pancoast-syndrome")])
g("g-cortical-ribbon-sign", "Cortical ribbon sign", "Gyriform restricted diffusion or T2 hyperintensity of the cortex, seen in prion disease, after hypoxia (laminar necrosis), in status epilepticus and in some encephalitides.", ["g-dwi", "g-periodic-discharges"], [R("sp-creutzfeldt-jakob-disease"), R("sp-hypoxic-ischemic-encephalopathy")])
g("g-decorticate-posturing", "Decorticate posturing", "Flexion of the arms with extension of the legs in response to pain, indicating dysfunction above the red nucleus (hemispheres, diencephalon) with intact rubrospinal tone.", ["g-decerebrate-posturing", "g-herniation"], [R("sp-decorticate-posturing"), R("sp-decerebrate-and-decorticate-posturing")])
g("g-decerebrate-posturing", "Decerebrate posturing", "Extension and internal rotation of the arms and extension of the legs in response to pain, indicating damage between the red nucleus and the vestibular nuclei (midbrain-pons), where unopposed vestibulospinal and pontine reticulospinal tone drives the extensors; a worse sign than decorticate posturing.", ["g-decorticate-posturing", "g-herniation"], [R("sp-decerebrate-and-decorticate-posturing")])
g("g-cheyne-stokes-respiration", "Cheyne-Stokes respiration", "A crescendo-decrescendo breathing pattern with apneic pauses, from bilateral hemispheric or diencephalic dysfunction or from heart failure; central neurogenic hyperventilation, apneustic and ataxic breathing mark progressively lower brainstem levels.", ["g-decorticate-posturing"])
g("g-locked-in-state", "Locked-in state", "Complete paralysis of the limbs and lower cranial nerves with preserved consciousness and vertical eye movements, from a lesion of the ventral pons that spares the tegmentum; must be distinguished from coma by asking for a blink or upward gaze.", ["g-akinetic-mutism", "g-vegetative-state"], [R("sp-locked-in-syndrome")])
g("g-vegetative-state", "Vegetative state (unresponsive wakefulness)", "Wakefulness with sleep-wake cycles, open eyes and reflex movements but no evidence of awareness, after diffuse cortical or thalamic damage with a preserved brainstem; the minimally conscious state shows inconsistent but reproducible signs of awareness.", ["g-locked-in-state", "g-brain-death"], [R("sp-coma"), R("sp-locked-in-syndrome"), R("sp-brain-death")])
g("g-brain-death", "Brain death", "Irreversible loss of all brainstem function: deep coma of known irreversible cause without confounders, absent pupillary, corneal, oculocephalic, caloric, gag and cough reflexes, no cranial motor response and apnea on a formal test; spinal reflexes may persist.", ["g-vegetative-state"], [R("sp-brain-death")])
g("g-glasgow-coma-scale", "Glasgow Coma Scale", "A 3-15 point scale of eye opening (1-4), verbal response (1-5) and motor response (1-6) that grades the level of consciousness; 8 or less defines coma. The FOUR score adds brainstem reflexes and breathing.", ["g-decorticate-posturing"], [R("sp-glasgow-coma-scale")])
g("g-duret-hemorrhage", "Duret hemorrhage", "Linear or flame-shaped hemorrhages in the midline of the pons and midbrain caused by stretching of perforating arteries during downward transtentorial herniation; a sign of a usually fatal stage.", ["g-herniation"], [R("sp-duret-hemorrhages")])
g("g-kernohan-notch", "Kernohan's notch", "Compression of the contralateral cerebral peduncle against the opposite tentorial edge during uncal herniation, producing a hemiparesis on the same side as the mass, a false localizing sign.", ["g-herniation", "g-false-localizing-sign"], [R("sp-uncal-herniation"), R("sp-transtentorial-herniation"), R("sp-brain-herniation")])
g("g-trendelenburg-sign", "Trendelenburg sign", "Dropping of the pelvis toward the swing leg when standing on one foot, from weakness of the gluteus medius and minimus; a sign of superior gluteal nerve injury, L5 root lesions or hip disease, producing a waddling gait when bilateral.", ["g-myotome"], [R("sp-trendelenburg-sign")])
g("g-cremasteric-reflex", "Cremasteric reflex", "Elevation of the testis when the medial thigh is stroked; the afferent runs in the ilioinguinal nerve and the efferent in the genitofemoral nerve (L1-L2). Lost in L1-L2 lesions and in corticospinal lesions above them.", ["g-dermatome"], [R("sp-cremasteric-reflex")])
g("g-wartenberg-syndrome", "Wartenberg syndrome (cheiralgia paresthetica)", "Entrapment of the superficial branch of the radial nerve where it pierces the forearm fascia or under a tight wrist band or handcuff, producing pain and paresthesias of the dorsolateral hand and thumb without weakness.", ["g-mononeuropathy", "g-tinel-sign"], [R("sp-cheiralgia-paresthetica"), R("sp-radial-nerve")])
g("g-hoover-sign", "Hoover sign", "In functional leg weakness, the 'weak' leg extends at the hip involuntarily when the patient flexes the other hip against resistance; a positive sign of functional weakness, not merely an absence of organic findings.", ["g-upper-motor-neuron"], [R("sp-functional-neurologic-disorder"), R("sp-somatic-symptom-disorder")])

write(E)
